content:
Use `.apply()` to transform Pulumi outputs and obtain the database password from encrypted stack configuration rather than wrapping a plaintext literal.

### `index.ts`

```ts
import * as pulumi from "@pulumi/pulumi";
import * as aws from "@pulumi/aws";

const config = new pulumi.Config();
const env = config.get("env") ?? pulumi.getStack();

if (env !== "dev" && env !== "prod") {
    throw new Error(`Unsupported environment "${env}"; expected "dev" or "prod".`);
}

const isProd = env === "prod";

// Must be configured with `pulumi config set --secret dbPassword ...`.
const dbPassword = config.requireSecret("dbPassword");

// S3 bucket
const bucket = new aws.s3.Bucket("app-bucket", {
    bucket: `myapp-assets-${env}`,
    versioning: {
        enabled: true,
    },
    serverSideEncryptionConfiguration: {
        rule: {
            applyServerSideEncryptionByDefault: {
                sseAlgorithm: "AES256",
            },
        },
    },
    tags: {
        Environment: env,
        Project: "myapp",
    },
});

new aws.s3.BucketPublicAccessBlock("app-bucket-public-access-block", {
    bucket: bucket.id,
    blockPublicAcls: true,
    blockPublicPolicy: true,
    ignorePublicAcls: true,
    restrictPublicBuckets: true,
});

// Transform the Output with apply; do not await it.
const bucketUrl = bucket.bucketRegionalDomainName.apply(
    hostname => `https://${hostname}`,
);

// RDS PostgreSQL
const db = new aws.rds.Instance("app-db", {
    instanceClass: isProd ? "db.t3.medium" : "db.t3.micro",
    engine: "postgres",
    engineVersion: "16.1",
    allocatedStorage: 20,
    dbName: "appdb",
    username: "app-user",
    password: dbPassword,

    multiAz: isProd,
    storageEncrypted: isProd,
    publiclyAccessible: false,
    deletionProtection: true,
    backupRetentionPeriod: 7,

    // Retain a final snapshot if the instance is intentionally destroyed.
    skipFinalSnapshot: false,
    finalSnapshotIdentifier: `myapp-${env}-final-snapshot`,

    tags: {
        Environment: env,
        Project: "myapp",
    },
});

export const bucketEndpoint = bucketUrl;
export const dbEndpoint = db.endpoint;
```

Configure each stack independently:

```bash
pulumi stack select dev
pulumi config set env dev
pulumi config set aws:region us-east-1
pulumi config set --secret dbPassword '<dev-password>'

pulumi stack select prod
pulumi config set env prod
pulumi config set aws:region us-east-1
pulumi config set --secret dbPassword '<prod-password>'
```

This fixes both preview issues:

- `bucketUrl` is now an `Output<string>`, produced via `.apply()`, rather than a `Promise`.
- `dbPassword` is a secret `Output<string>` backed by encrypted Pulumi stack configuration, not plaintext wrapped with `pulumi.output()`.
